src/pages/Settings/System/SystemSettings.source:
import BiotechIcon from "@mui/icons-material/Biotech";
import Box from "@mui/material/Box";
import Chip from "@mui/material/Chip";
import Switch from "@mui/material/Switch";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Tooltip from "@mui/material/Tooltip";
import type React from "react";
import { useCallback, useContext, useEffect, useState } from "react";
import { LicenseTooltip } from "../../../components/App/License/LicenseToolTip";
import InputGroup from "../../../components/Common/InputGroup/InputGroup";
import { TerminologyConfiguration } from "../../../components/TerminologyConfiguration";
import type { ILicenseStatus } from "../../../models/ILicenseStatus";
import type { IOptionalFeature } from "../../../models/OptionalFeatures/OptionalFeature";
import { TERMINOLOGY_KEYS } from "../../../models/TerminologyKeys";
import { ApiServiceContext } from "../../../services/Api/ApiServiceContext";
import { useTerminology } from "../../../services/TerminologyContext";
import RefreshSettingUpdater from "../Refresh/RefreshSettingUpdater";
import BlackoutSettings from "./BlackoutSettings";
import FeatureOrderingSettings from "./FeatureOrderingSettings";

const SystemSettingsTab: React.FC = () => {
	const [optionalFeatures, setOptionalFeatures] = useState<IOptionalFeature[]>(
		[],
	);

	const [licenseStatus, setLicenseStatus] = useState<ILicenseStatus | null>(
		null,
	);

	const { optionalFeatureService, licensingService } =
		useContext(ApiServiceContext);

	const { getTerm } = useTerminology();
	const featureTerm = getTerm(TERMINOLOGY_KEYS.FEATURE);
	const teamTerm = getTerm(TERMINOLOGY_KEYS.TEAM);

	const fetchOptionalFeatures = useCallback(async () => {
		const optionalFeatureData = await optionalFeatureService.getAllFeatures();
		if (optionalFeatureData) {
			setOptionalFeatures(optionalFeatureData);
		}
	}, [optionalFeatureService]);

	const fetchLicenseStatus = useCallback(async () => {
		try {
			const licenseData = await licensingService.getLicenseStatus();
			setLicenseStatus(licenseData);
		} catch (error) {
			console.error("Failed to fetch license status:", error);
			setLicenseStatus(null);
		}
	}, [licensingService]);

	const onToggleOptionalFeature = async (toggledFeature: IOptionalFeature) => {
		const updatedFeatures = optionalFeatures.map((feature) =>
			feature.id === toggledFeature.id
				? { ...feature, enabled: !feature.enabled }
				: feature,
		);
		setOptionalFeatures(updatedFeatures);

		try {
			await optionalFeatureService.updateFeature({
				...toggledFeature,
				enabled: !toggledFeature.enabled,
			});
		} catch {
			await fetchOptionalFeatures();
		}
	};

	useEffect(() => {
		fetchOptionalFeatures();
		fetchLicenseStatus();
	}, [fetchOptionalFeatures, fetchLicenseStatus]);

	return (
		<Box sx={{ mb: 4 }}>
			<InputGroup
				title="Blackout Periods & Recurring Rules"
				initiallyExpanded={true}
			>
				<BlackoutSettings
					isPremium={licenseStatus?.canUsePremiumFeatures ?? false}
				/>
			</InputGroup>

			{optionalFeatures.length > 0 && (
				<InputGroup title="Optional Features" initiallyExpanded={true}>
					<TableContainer>
						<Table data-testid="optional-features-table">
							<TableHead>
								<TableRow>
									<TableCell>Name</TableCell>
									<TableCell>Description</TableCell>
									<TableCell>Enabled</TableCell>
								</TableRow>
							</TableHead>
							<TableBody>
								{optionalFeatures.map((feature) => (
									<LicenseTooltip
										key={feature.id}
										canUseFeature={
											!feature.isPremium ||
											(licenseStatus?.canUsePremiumFeatures ?? false)
										}
										premiumExtraInfo=""
										defaultTooltip=""
									>
										<TableRow
											key={feature.id}
											data-testid={`feature-row-${feature.key}`}
										>
											<TableCell>
												<Box sx={{ display: "flex", alignItems: "center" }}>
													{feature.name}
													{feature.isPreview && (
														<Tooltip title="This feature is in preview and may change or be removed in future versions">
															<Chip
																icon={<BiotechIcon />}
																label="Preview"
																size="small"
																color="warning"
																sx={{ ml: 1 }}
																data-testid={`${feature.key}-preview-indicator`}
															/>
														</Tooltip>
													)}
												</Box>
											</TableCell>
											<TableCell>{feature.description}</TableCell>
											<TableCell>
												<Switch
													checked={feature.enabled}
													data-testid={`${feature.key}-toggle`}
													disabled={
														feature.isPremium &&
														!(licenseStatus?.canUsePremiumFeatures ?? false)
													}
													onChange={() => onToggleOptionalFeature(feature)}
													color="primary"
												/>
											</TableCell>
										</TableRow>
									</LicenseTooltip>
								))}
							</TableBody>
						</Table>
					</TableContainer>
				</InputGroup>
			)}

			<InputGroup title={`${featureTerm} Order`} initiallyExpanded={true}>
				<FeatureOrderingSettings
					isPremium={licenseStatus?.canUsePremiumFeatures ?? false}
				/>
			</InputGroup>

			<InputGroup title="Terminology Configuration" initiallyExpanded={true}>
				<TerminologyConfiguration />
			</InputGroup>

			<InputGroup title={`${teamTerm} Refresh`}>
				<RefreshSettingUpdater title={teamTerm} settingName="Team" />
			</InputGroup>
			<InputGroup title={`${featureTerm} Refresh`}>
				<RefreshSettingUpdater title={featureTerm} settingName="Feature" />
			</InputGroup>
		</Box>
	);
};

export default SystemSettingsTab;

src/pages/Settings/Encryption/Encryption.source:
import Alert from "@mui/material/Alert";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Chip from "@mui/material/Chip";
import Link from "@mui/material/Link";
import Stack from "@mui/material/Stack";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Typography from "@mui/material/Typography";
import type React from "react";
import { useCallback, useContext, useEffect, useState } from "react";
import InputGroup from "../../../components/Common/InputGroup/InputGroup";
import {
	type EncryptionKeyState,
	KEY_CUSTODY_WORDING,
	type KeyCustody,
} from "../../../models/Encryption/EncryptionKeyState";
import {
	SECRET_OUTCOME_WORDING,
	type SecretOutcomeNeedingAttention,
	type SecretReadabilityReport,
	type StoredSecret,
} from "../../../models/Encryption/SecretReadabilityReport";
import { ApiServiceContext } from "../../../services/Api/ApiServiceContext";

// Where the key is not Lighthouse's to replace, the panel says who it belongs to and what that person
// does about it. It never draws a Rotate control that cannot be honoured - not even a disabled one,
// because a control that exists and cannot be used teaches the wrong model of who owns what.
const WHO_OWNS_THE_KEY: Record<KeyCustody, string> = {
	GeneratedForThisInstance:
		"Lighthouse made this key and keeps it, so it can make a new one for you.",
	SuppliedByConfiguration:
		"This key was supplied through the instance's configuration, so it belongs to whoever set it.",
	SuppliedByExternalSecret:
		"This key was supplied from a mounted secret, so it belongs to whoever keeps that secret.",
	NoDurableStore:
		"This instance has nowhere to keep a key that would still be there after a restart, so it is running on the key published with the product. Set Encryption__Key, or set Encryption__KeyStorePath to a directory that outlives this container, and start Lighthouse again.",
};

// The only rotation procedure this population is ever given, and the one observed could not be
// followed: it named Encryption__Keys when the operator had set Encryption__Key - two names differing
// by one character, with different grammars, and it never said the plural existed or that it wins. It
// gave no separator either, so an operator guessing a newline got a startup refusal. Everything
// somebody has to type is now in it, including which entry becomes the key in force.
//
// The same sentence reaches every Kubernetes operator through the mounted-secret custody, so it is
// written once and told where to put the value rather than twice.
const RETIRED_SETTING = "EncryptionSettings__EncryptionKey";

const howToReplaceIt = (keyState: EncryptionKeyState) => {
	const answered = keyState.keySuppliedThrough ?? "Encryption__Key";
	// Where the retired name is what answered, it is the one setting the instruction must not send an
	// operator back to: a key put there works today and stops being read in a future release. The
	// startup banner says so, and nobody running as a service or a container ever reads a banner.
	const setting = answered === RETIRED_SETTING ? "Encryption__Key" : answered;
	const where =
		keyState.custody === "SuppliedByExternalSecret"
			? `the file ${setting} points at, then restart the pod`
			: `${setting}, then start Lighthouse again`;

	return (
		(answered === RETIRED_SETTING
			? `This instance read its key from ${RETIRED_SETTING}, which this release retired. It still ` +
				"works today and will stop being read in a future release: set the same value as " +
				"Encryption__Key and remove the old one. The key itself does not change, and nothing " +
				"stored has to be re-entered. "
			: "") +
		`To replace it, put the new key first in ${where}. ` +
		"More than one key is written as a comma-separated list, each entry either the base64 key on its " +
		"own or name:base64, and the first entry is the one new secrets are written under - the rest are " +
		"kept so that what was already stored stays readable. Encryption__Key and Encryption__Keys both " +
		"take that list and the plural wins if you set both, so leaving the old one in place is harmless. " +
		"Then move the stored secrets onto the new key."
	);
};

// Only an instance that made its own key keeps one. Everywhere else the key store directory exists,
// is full of key-shaped files - the data protection key, the OAuth state secret - and does not hold the
// encryption key at all. An operator who backed that folder up alongside the database had every reason
// to believe they had taken their key with them, and had not.
const whereTheKeyIsLabel = (keyState: EncryptionKeyState) =>
	keyState.custody === "GeneratedForThisInstance"
		? "Kept in"
		: "Supplied through";

const whereTheKeyIs = (keyState: EncryptionKeyState) => {
	if (keyState.custody === "GeneratedForThisInstance") {
		return keyState.keyStorePath;
	}

	if (keyState.custody === "NoDurableStore") {
		return "nowhere - this instance has no key of its own";
	}

	return keyState.keySuppliedThrough ?? "Encryption__Key";
};

const KeyRing: React.FC<{ keyState: EncryptionKeyState }> = ({ keyState }) => (
	<TableContainer>
		<Table data-testid="encryption-key-ring">
			<TableBody>
				<TableRow>
					<TableCell>Key source</TableCell>
					<TableCell data-testid="encryption-custody">
						{KEY_CUSTODY_WORDING[keyState.custody]}
					</TableCell>
				</TableRow>
				<TableRow>
					<TableCell>Active key</TableCell>
					<TableCell data-testid="encryption-active-key-id">
						{keyState.activeKeyId}
					</TableCell>
				</TableRow>
				<TableRow>
					<TableCell>Keys held</TableCell>
					<TableCell>
						<Stack
							direction="row"
							spacing={1}
							useFlexGap
							sx={{ flexWrap: "wrap" }}
						>
							{keyState.keyIds.map((keyId) => (
								<Chip
									key={keyId}
									label={keyId}
									size="small"
									data-testid={`encryption-key-${keyId}`}
								/>
							))}
						</Stack>
					</TableCell>
				</TableRow>
				<TableRow>
					<TableCell>{whereTheKeyIsLabel(keyState)}</TableCell>
					<TableCell data-testid="encryption-key-store-path">
						{whereTheKeyIs(keyState)}
					</TableCell>
				</TableRow>
			</TableBody>
		</Table>
	</TableContainer>
);

// Whether moving the stored secrets would achieve anything. The listed keys are the ones something is
// actually stored under, so any of them other than the key in force is work a move would do - which
// covers secrets left on the published key and secrets left on an earlier key without asking twice.
//
// Where the key in force IS the published key there is nowhere to move anything to: the move would
// re-encrypt that key onto itself, change nothing, and leave the warning standing. What fixes that
// instance is giving it a key of its own, which the custody sentence above the buttons already says.
//
// Everywhere else the question is whether anything readable is off the key in force, and only the server
// can answer it. Asking the list of keys instead - as this did until a real upgraded instance showed
// otherwise - misses every credential written before the envelope format, because such a value carries no
// key id for anything to list.
const movingWouldAchieveSomething = (keyState: EncryptionKeyState) =>
	keyState.custody !== "NoDurableStore" &&
	keyState.readableSecretsNotOnTheActiveKey > 0;

// A secret that moved needs no listing - the count already says so. What an operator has to act on is
// what was left behind, and the only useful thing to say about it is which Connection and which field.
const wasLeftBehind = (
	secret: StoredSecret,
): secret is StoredSecret & { outcome: SecretOutcomeNeedingAttention } =>
	secret.outcome === "CouldNotBeRead" ||
	secret.outcome === "CouldNotBeWritten" ||
	secret.outcome === "NotEncrypted";

// A check moves nothing, so a summary counting what moved would greet an operator with "Moved 0" on a
// perfectly healthy instance. The two actions answer different questions and are said in different words.
// Three, not two. Rotating and moving both write, but only one of them makes a key, and a rotation
// reported in the vocabulary of a move says nothing about the thing that actually happened.
type WhatWasAsked = "check" | "move" | "rotate";

const secrets = (count: number) =>
	count === 1 ? "1 stored secret" : `${count} stored secrets`;

const credentials = (count: number) =>
	count === 1 ? "1 stored credential is" : `${count} stored credentials are`;

const itOrThem = (count: number) => (count === 1 ? "it" : "them");

// Both sentences are built here rather than inline: a ternary inside a template-literal slot counts as
// nested under any enclosing conditional, and each alert sits inside one.
const whatToDoAboutThePublishedKey = (keyState: EncryptionKeyState) => {
	const opening = `${credentials(keyState.secretsUnderPublishedKey)} still encrypted with the key published with Lighthouse.`;

	if (!movingWouldAchieveSomething(keyState)) {
		return `${opening} This instance has no key of its own to move them onto: give it one as described above, start Lighthouse again, and the move is offered here.`;
	}

	return `${opening} Move ${itOrThem(keyState.secretsUnderPublishedKey)} onto this instance's own key — nothing has to be re-entered.`;
};

const whatIsOffTheKeyInForce = (keyState: EncryptionKeyState) => {
	const count = keyState.readableSecretsNotOnTheActiveKey;
	const pronoun = itOrThem(count);

	return `${credentials(count)} readable and not on the key in force — written under an earlier key, or in the older format this release replaced. Moving ${pronoun} re-encrypts ${pronoun} under the active key. Nothing has to be re-entered.`;
};

// A count of zero is not information. Four categories of nothing compete with the one number that
// matters, and the number that matters is always one of the few that are not zero - so only those are
// said. An operator reads a count above zero as something they may have to do.
const whatEachOneIs = (report: SecretReadabilityReport) =>
	[
		[report.onActiveKeyCount, `on the key in force ${report.activeKeyId}`],
		[report.onRetiredKeyCount, "on an earlier key"],
		[report.plaintextCount, "never encrypted"],
		[report.unreadableCount, "could not be read"],
	]
		.filter(([count]) => (count as number) > 0)
		.map(([count, what]) => `${count} ${what}`)
		.join(", ");

const couldNotBeRead = (report: SecretReadabilityReport) =>
	report.unreadableCount > 0
		? ` ${secrets(report.unreadableCount)} could not be read.`
		: "";

const summaryOf = (asked: WhatWasAsked, report: SecretReadabilityReport) => {
	// Said instead of the counts rather than after them. Those counts describe a rotation that did not
	// finish, and an operator who reads "moved 46" stops there - the one thing they have to do is run it
	// again, and anything printed before that competes with it.
	if (report.keysChangedWhileItRan) {
		return `The encryption keys changed while this was running, so it did not finish - run it again.${couldNotBeRead(report)}`;
	}

	// Rotation leads with the key it made, because that is what happened and it happens whether or not
	// there was anything to move. On an empty instance this used to read "Moved 0 stored secrets onto key
	// k-…", which is the one fact it did not report.
	if (asked === "rotate") {
		const moved =
			report.movedCount > 0
				? ` ${secrets(report.movedCount)} moved onto it.`
				: "";

		return `Made key ${report.activeKeyId} and put it in force.${moved}${couldNotBeRead(report)}`;
	}

	if (asked === "move") {
		return report.movedCount === 0
			? `Nothing needed moving - every stored secret was already on key ${report.activeKeyId}.${couldNotBeRead(report)}`
			: `Moved ${secrets(report.movedCount)} onto key ${report.activeKeyId}.${couldNotBeRead(report)}`;
	}

	return report.secrets.length === 0
		? "Checked every stored secret. There are none yet."
		: `Checked ${secrets(report.secrets.length)}: ${whatEachOneIs(report)}.`;
};

const WhatHappened: React.FC<{
	asked: WhatWasAsked;
	report: SecretReadabilityReport;
}> = ({ asked, report }) => {
	const leftBehind = report.secrets.filter(wasLeftBehind);
	const needsAttention = leftBehind.length > 0 || report.keysChangedWhileItRan;

	return (
		<Box sx={{ mt: 2 }} data-testid="encryption-report">
			<Alert
				severity={needsAttention ? "warning" : "success"}
				data-testid="encryption-report-summary"
			>
				{summaryOf(asked, report)}
			</Alert>

			{leftBehind.length > 0 && (
				<TableContainer sx={{ mt: 2 }}>
					<Table size="small" data-testid="encryption-report-secrets">
						<TableHead>
							<TableRow>
								<TableCell>Connection</TableCell>
								<TableCell>Field</TableCell>
								<TableCell>What happened</TableCell>
							</TableRow>
						</TableHead>
						<TableBody>
							{leftBehind.map((secret) => (
								<TableRow key={`${secret.connectionId}-${secret.field}`}>
									<TableCell>{secret.connectionName}</TableCell>
									<TableCell>{secret.field}</TableCell>
									<TableCell>
										{SECRET_OUTCOME_WORDING[secret.outcome]}
									</TableCell>
								</TableRow>
							))}
						</TableBody>
					</Table>
				</TableContainer>
			)}
		</Box>
	);
};

const EncryptionPanel: React.FC = () => {
	const [keyState, setKeyState] = useState<EncryptionKeyState | null>(null);
	const [report, setReport] = useState<SecretReadabilityReport | null>(null);
	const [asked, setAsked] = useState<WhatWasAsked>("move");
	const [failure, setFailure] = useState<string | null>(null);
	const [busy, setBusy] = useState(false);

	const { encryptionService } = useContext(ApiServiceContext);

	const readKeyState = useCallback(async () => {
		try {
			setKeyState(await encryptionService.getKeyState());
		} catch {
			setKeyState(null);
		}
	}, [encryptionService]);

	useEffect(() => {
		readKeyState();
	}, [readKeyState]);

	const run = async (
		whatWasAsked: WhatWasAsked,
		action: () => Promise<SecretReadabilityReport>,
	): Promise<void> => {
		setBusy(true);
		setFailure(null);

		try {
			setReport(await action());
			setAsked(whatWasAsked);
			await readKeyState();
		} catch (error_) {
			setFailure(
				error_ instanceof Error
					? error_.message
					: "The stored secrets could not be moved.",
			);
		} finally {
			setBusy(false);
		}
	};

	const moveThemOntoTheActiveKey = () =>
		run("move", () => encryptionService.reEncryptSecrets());

	if (keyState === null) {
		return null;
	}

	return (
		<InputGroup title="Secret Encryption Key" initiallyExpanded={true}>
			{/* Read cold, this screen used to open on a table whose first row is "Key source", with nothing
			    saying what any of it is about. One line, and the documentation does the teaching. */}
			<Typography variant="body2" data-testid="encryption-subject">
				How the credentials stored in your Connections are encrypted at rest.{" "}
				<Link
					href="https://docs.lighthouse.letpeople.work/settings/encryption.html"
					target="_blank"
					rel="noopener"
					data-testid="encryption-docs-link"
				>
					Read more
				</Link>
			</Typography>

			<Box sx={{ mt: 2 }}>
				<KeyRing keyState={keyState} />
			</Box>

			<Typography
				variant="body2"
				sx={{ mt: 2 }}
				data-testid="encryption-custody-explanation"
			>
				{WHO_OWNS_THE_KEY[keyState.custody]}
				{keyState.keySuppliedThrough !== null &&
					keyState.keySuppliedThrough !== undefined &&
					` ${howToReplaceIt(keyState)}`}
			</Typography>

			{keyState.allowsStartWithUnreadableSecrets && (
				<Alert
					severity="error"
					sx={{ mt: 2 }}
					data-testid="started-past-the-refusal-notice"
				>
					{
						"This instance was started with Encryption__StartEvenIfNothingStoredCanBeRead set, so it is running with stored credentials it cannot read. Press Check secrets below for the Connection and field each one sits in, enter those credentials again, then remove the setting and restart. If this instance has nowhere durable to keep a key — a container keeping its key store on the writable layer — give it one first with Encryption__KeyStorePath or Encryption__Key: removing the setting means restarting, and a restart would take the new key with it."
					}
				</Alert>
			)}

			{keyState.secretsUnderPublishedKey === 0 &&
				movingWouldAchieveSomething(keyState) && (
					<Alert
						severity="info"
						sx={{ mt: 2 }}
						data-testid="not-on-the-active-key-notice"
					>
						{whatIsOffTheKeyInForce(keyState)}
					</Alert>
				)}

			{keyState.secretsUnderPublishedKey > 0 && (
				<Alert
					severity="warning"
					sx={{ mt: 2 }}
					data-testid="published-key-notice"
				>
					{whatToDoAboutThePublishedKey(keyState)}
				</Alert>
			)}

			<Stack direction="row" spacing={2} sx={{ mt: 2 }}>
				{keyState.canMint && (
					<Button
						variant="outlined"
						disabled={busy}
						data-testid="rotate-key-button"
						onClick={() => run("rotate", () => encryptionService.rotateKey())}
					>
						Rotate key
					</Button>
				)}
				{movingWouldAchieveSomething(keyState) && (
					<Button
						variant={
							keyState.secretsUnderPublishedKey > 0 ? "contained" : "outlined"
						}
						disabled={busy}
						data-testid="reencrypt-button"
						onClick={moveThemOntoTheActiveKey}
					>
						Move stored secrets
					</Button>
				)}
				<Button
					variant="text"
					disabled={busy}
					data-testid="check-secrets-button"
					onClick={() => run("check", () => encryptionService.checkSecrets())}
				>
					Check secrets
				</Button>
			</Stack>

			{failure !== null && (
				<Alert severity="error" sx={{ mt: 2 }} data-testid="encryption-failure">
					{failure}
				</Alert>
			)}

			{report !== null && <WhatHappened asked={asked} report={report} />}
		</InputGroup>
	);
};

export default EncryptionPanel;

src/models/Encryption/EncryptionKeyState.source:
import { z } from "zod";

export const KEY_CUSTODY_VALUES = [
	"NoDurableStore",
	"GeneratedForThisInstance",
	"SuppliedByConfiguration",
	"SuppliedByExternalSecret",
] as const;

export type KeyCustody = (typeof KEY_CUSTODY_VALUES)[number];

export interface EncryptionKeyState {
	custody: KeyCustody;
	canMint: boolean;
	activeKeyId: string;
	keyIds: string[];
	keyStorePath: string;
	legacyDefaultPresent: boolean;
	secretsUnderPublishedKey: number;
	// How many stored credentials can be read and are not on the key in force - the number that decides
	// whether moving them would achieve anything. It cannot be worked out from the key list: a credential
	// written before the envelope format carries no key id, so nothing names the key that wrote it.
	readableSecretsNotOnTheActiveKey: number;
	allowsStartWithUnreadableSecrets: boolean;
	// The setting the key arrived in, or null where Lighthouse keeps the key itself. It is what the
	// rotation instruction has to name: the one observed named a setting the operator had not set.
	keySuppliedThrough: string | null;
}

export const EncryptionKeyStateSchema = z.object({
	custody: z.enum(KEY_CUSTODY_VALUES),
	canMint: z.boolean(),
	activeKeyId: z.string(),
	keyIds: z.array(z.string()),
	keyStorePath: z.string(),
	legacyDefaultPresent: z.boolean(),
	secretsUnderPublishedKey: z.number(),
	readableSecretsNotOnTheActiveKey: z.number(),
	allowsStartWithUnreadableSecrets: z.boolean(),
	keySuppliedThrough: z.string().nullable(),
});

// A self-hoster reading this screen is asking whether the key is theirs to keep, not what the
// server calls the case internally. The same four phrasings are what the startup log prints.
export const KEY_CUSTODY_WORDING: Record<KeyCustody, string> = {
	NoDurableStore: "the key published with the product",
	GeneratedForThisInstance: "generated for this instance",
	SuppliedByConfiguration: "supplied by configuration",
	SuppliedByExternalSecret: "supplied by a mounted secret file",
};

